AND DATE_FORMAT(s.stat_month, '%Y%m') = REPLACE(#{query.statMonth}, '-', '')
AND s.stat_month = (SELECT MAX(latest.stat_month) FROM t_sr_strategy_period_summary_ap_key_audience latest WHERE latest.tab_type = 'active' AND latest.is_deleted = 0 AND EXISTS (SELECT 1 FROM t_sr_strategy_key_audience t WHERE t.strategy_code COLLATE utf8mb4_unicode_ci = latest.strategy_id COLLATE utf8mb4_unicode_ci AND t.tab_type = 'active' AND t.is_deleted = 0 AND t.customer_group = #{query.customerGroup})
AND latest.city_id = #{query.cityId}
AND latest.county_id = #{query.countyId}
)
AND s.strategy_class = #{query.strategyClass}
AND s.city_id = #{query.cityId}
AND s.county_id = #{query.countyId}
ORDER BY keyName

