mapper.select:
SELECT MAX(REPLACE(k.stat_month, '-', ''))
FROM  k
WHERE k.tab_type = #{tabType}
  AND k.is_deleted = 0

    AND k.strategy_class = #{strategyClass}


    AND k.strategy_class IN ('升接', '稳', '重点客群')

SELECT DATE_FORMAT(MAX(c.stat_month), '%Y%m')
FROM  c
WHERE c.tab_type = #{tabType}
  AND (c.channel = #{channel} OR CONVERT(c.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d
      WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0
        AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)
  ))
  AND c.is_deleted = 0
  AND c.strategy_class = #{strategyClass}
  AND c.city_id = #{cityId}
  AND c.county_id = #{countyId}

SELECT MAX(REPLACE(sub.stat_month, '-', ''))
FROM (
    SELECT stat_month FROM 
    WHERE is_deleted = 0
    AND tab_type = #{tabType}
    AND strategy_class = #{strategyClass}
    AND strategy_class IN ('升接', '稳', '重点客群')
    AND city_id = #{cityId}
    AND county_id = #{countyId}

        UNION ALL
        SELECT stat_month FROM t_sr_strategy_period_summary_ctrl
        WHERE is_deleted = 0
        AND city_id = #{cityId}
        AND county_id = #{countyId}

) sub



        SELECT DATE_FORMAT(c.stat_month, '%Y%m') AS month,
               c.${metricColumn} AS value, c.${metricColumn}_qoq AS qoq
        FROM t_sr_channel_summary_ctrl c
        WHERE (c.channel = #{channel} OR CONVERT(c.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0))) AND c.is_deleted = 0
          AND DATE_FORMAT(c.stat_month, '%Y-%m') <= #{statMonth}
        AND c.city_id = #{cityId}
        AND c.county_id = #{countyId}


        SELECT DATE_FORMAT(c.stat_month, '%Y%m') AS month,
               c.${metricColumn} AS value, c.${metricColumn}_qoq AS qoq
        FROM  c
        WHERE c.tab_type = #{tabType} AND (c.channel = #{channel} OR CONVERT(c.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0))) AND c.is_deleted = 0
          AND DATE_FORMAT(c.stat_month, '%Y-%m') <= #{statMonth}
        AND c.city_id = #{cityId}
        AND c.county_id = #{countyId}

            AND c.strategy_class = #{strategyClass}

            AND c.strategy_class = '全部'



ORDER BY c.stat_month DESC LIMIT 12

SELECT DATE_FORMAT(c.stat_month, '%Y%m') AS month, ROUND(c.reach_count * 100.0 / NULLIF(c.usage_count, 0), 2) AS value, ROUND(ROUND(c.reach_count * 100.0 / NULLIF(c.usage_count, 0), 2) - ROUND(p.reach_count * 100.0 / NULLIF(p.usage_count, 0), 2), 2) AS qoq, '%' AS unit FROM c LEFT JOIN p ON p.tab_type = c.tab_type AND p.strategy_class = c.strategy_class AND p.channel = c.channel AND p.city_id <=> c.city_id AND p.county_id <=> c.county_id AND p.is_deleted = 0 AND p.stat_month = DATE_SUB(c.stat_month, INTERVAL 1 MONTH) WHERE c.tab_type = #{tabType} AND (c.channel = #{channel} OR CONVERT(c.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0))) AND c.is_deleted = 0 AND DATE_FORMAT(c.stat_month, '%Y-%m') <= #{statMonth} AND c.city_id = #{cityId} AND c.county_id = #{countyId}
AND c.strategy_class = #{strategyClass} AND c.strategy_class = '全部'
ORDER BY c.stat_month DESC LIMIT 12

choose.when:
SELECT c.channel AS channel, COALESCE(d.key_name COLLATE utf8mb4_unicode_ci, c.channel COLLATE utf8mb4_unicode_ci) AS channelName, c.strategy_count AS strategyCount, c.strategy_count_qoq AS strategyCountQoQ, c.consult_count AS consultCount, c.consult_count_qoq AS consultCountQoQ, c.retain_count AS retainCount, c.retain_count_qoq AS retainCountQoQ, c.retain_rate AS retainRate, c.retain_rate_qoq AS retainRateQoQ, c.dispatch_count AS dispatchCount, c.dispatch_count_qoq AS dispatchCountQoQ, c.success_count AS successCount, c.success_count_qoq AS successCountQoQ, c.success_rate AS successRate, c.success_rate_qoq AS successRateQoQ, c.income AS income, c.income_qoq AS incomeQoQ FROM t_sr_channel_summary_ctrl c LEFT JOIN t_sr_dim_channel d ON d.key_code COLLATE utf8mb4_unicode_ci = c.channel COLLATE utf8mb4_unicode_ci WHERE DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.strategy_class = #{strategyClass}
AND c.strategy_class = '全部'
AND c.city_id = #{cityId}
AND c.county_id = #{countyId}
AND (c.channel = #{channel} OR CONVERT(c.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))
AND c.channel !='全部'
ORDER BY
${orderByClause} c.strategy_count DESC

SELECT SUM(c.strategy_count) AS strategyCount, SUM(c.consult_count) AS consultCount, SUM(c.retain_count) AS retainCount, SUM(c.dispatch_count) AS dispatchCount, SUM(c.success_count) AS successCount, SUM(c.income) AS income FROM t_sr_channel_summary_ctrl c WHERE DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.city_id = #{cityId}
AND c.county_id = #{countyId}

choose.otherwise:
SELECT SUM(c.strategy_count) AS strategyCount, SUM(c.original_cust) AS originalCust, SUM(c.push_count) AS pushCount, SUM(c.usage_count) AS usageCount, SUM(c.reach_count) AS reachCount, SUM(c.target_conv_num) AS targetConvNum, SUM(c.product_conv_num) AS productConvNum, SUM(c.expected_income) AS expectedIncome, SUM(c.actual_income) AS actualIncome FROM c WHERE c.tab_type = #{tabType} AND DATE_FORMAT(c.stat_month, '%Y-%m') = #{statMonth} AND c.is_deleted = 0
AND c.strategy_class = #{strategyClass}
AND c.strategy_class = '全部'
AND c.city_id = #{cityId}
AND c.county_id = #{countyId}

mapper.sql:
WHERE s.tab_type = #{tabType}
  AND DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
  AND s.is_deleted = 0

    AND s.city_id = #{cityId}


    AND s.county_id = #{countyId}


    AND ((s.channel COLLATE utf8mb4_unicode_ci) = (#{channel} COLLATE utf8mb4_unicode_ci)
      OR (s.channel COLLATE utf8mb4_unicode_ci) IN (
        SELECT d.key_code COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d
        WHERE d.key_name COLLATE utf8mb4_unicode_ci = #{channel} COLLATE utf8mb4_unicode_ci
          AND d.status = 1 AND d.is_deleted = 0
          AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))


    AND s.big_category = #{bigCategory}


    AND s.small_category = #{smallCategory}


    AND s.strategy_name LIKE CONCAT('%', #{strategyName}, '%')



        AND s.strategy_class IN ('升接', '稳', '重点客群')


        AND s.strategy_class = #{strategyClass}




    AND EXISTS (SELECT 1 FROM t_sr_strategy_key_audience cg
    WHERE cg.strategy_code COLLATE utf8mb4_unicode_ci = s.strategy_id COLLATE utf8mb4_unicode_ci
      AND cg.tab_type = 'active'
          AND cg.strategy_class = '重点客群' AND cg.is_deleted = 0
          AND cg.customer_group = #{customerGroup})

WHERE DATE_FORMAT(s.stat_month, '%Y-%m') = #{statMonth}
  AND s.is_deleted = 0

    AND s.city_id = #{cityId}


    AND s.county_id = #{countyId}


    AND ((s.channel COLLATE utf8mb4_unicode_ci) = (#{channel} COLLATE utf8mb4_unicode_ci)
      OR (s.channel COLLATE utf8mb4_unicode_ci) IN (
        SELECT d.key_code COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d
        WHERE d.key_name COLLATE utf8mb4_unicode_ci = #{channel} COLLATE utf8mb4_unicode_ci
          AND d.status = 1 AND d.is_deleted = 0
          AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))


    AND s.big_category = #{bigCategory}


    AND s.small_category = #{smallCategory}


    AND s.strategy_name LIKE CONCAT('%', #{strategyName}, '%')



    AND s.small_category = #{productName}

choose.when:
SELECT CONCAT(LEFT(REPLACE(CAST(m.stat_month AS CHAR), '-', ''), 4), '-', SUBSTRING(REPLACE(CAST(m.stat_month AS CHAR), '-', ''), 5, 2)) AS month, m.capacity AS capacity, m.qoq AS qoq FROM t_sr_channel_monthly_capacity_ctrl m WHERE m.is_deleted = 0 AND REPLACE(LEFT(CAST(m.stat_month AS CHAR), 7), '-', '') <= REPLACE(#{statMonth}, '-', '')
AND (m.channel = #{channel} OR CONVERT(m.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))
AND m.channel ='全部'
AND m.big_category = #{bigCategory}
AND m.big_category ='全部'
AND m.small_category = #{smallCategory}
AND m.small_category ='全部'
AND m.city_id = #{cityId}
AND m.county_id = #{countyId}
ORDER BY m.stat_month DESC LIMIT 6

choose.otherwise:
SELECT CONCAT(LEFT(REPLACE(CAST(m.stat_month AS CHAR), '-', ''), 4), '-',
              SUBSTRING(REPLACE(CAST(m.stat_month AS CHAR), '-', ''), 5, 2), '-01') AS month,
       m.capacity   AS capacity,
       m.qoq        AS qoq
FROM  m
WHERE m.tab_type = #{tabType}
  AND m.is_deleted = 0

    AND m.strategy_class = #{strategyClass}

    AND m.strategy_class = '全部'

AND REPLACE(LEFT(CAST(m.stat_month AS CHAR), 7), '-', '') <= REPLACE(#{statMonth}, '-', '')


        AND (m.channel = #{channel} OR CONVERT(m.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))


        AND m.channel ='全部'




        AND m.big_category = #{bigCategory}


        AND m.big_category ='全部'




        AND m.small_category = #{smallCategory}


        AND m.small_category ='全部'



    AND m.city_id = #{cityId}


    AND m.county_id = #{countyId}

ORDER BY m.stat_month DESC
LIMIT 6

choose.when:
SELECT b.biz_name AS bizName, SUM(b.capacity) AS capacity, CASE WHEN SUM(CASE WHEN b.capacity IS NOT NULL AND (b.qoq IS NULL OR b.qoq <= -100) THEN 1 ELSE 0 END) > 0 THEN NULL WHEN SUM(CASE WHEN b.capacity IS NOT NULL THEN b.capacity / NULLIF(1 + b.qoq / 100.0, 0) ELSE 0 END) = 0 THEN NULL ELSE ROUND(( SUM(b.capacity) / SUM(CASE WHEN b.capacity IS NOT NULL THEN b.capacity / NULLIF(1 + b.qoq / 100.0, 0) ELSE 0 END) - 1 ) * 100, 4) END AS qoq FROM t_sr_channel_biz_capacity_ctrl b WHERE b.stat_month >= STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d') AND b.stat_month < DATE_ADD(STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) AND b.is_deleted = 0 AND b.biz_name != '全部'
AND b.channel != '全部' AND b.big_category != '全部' AND COALESCE(b.small_category, '') != '全部'
AND (b.channel = #{channel} OR CONVERT(b.channel USING utf8mb4) COLLATE utf8mb4_unicode_ci IN (SELECT CONVERT(d.key_code USING utf8mb4) COLLATE utf8mb4_unicode_ci FROM t_sr_dim_channel d WHERE d.key_name = #{channel} AND d.status = 1 AND d.is_deleted = 0 AND (d.tab_type = #{tabType} OR FIND_IN_SET(#{tabType}, d.tab_type) > 0)))
AND b.big_category = #{bigCategory}
AND b.small_category = #{smallCategory}
AND b.city_id = #{cityId}
AND b.county_id = #{countyId}
GROUP BY b.biz_name ORDER BY capacity DESC

choose.otherwise:
