SELECT DISTINCT b.biz_code AS bizCode, b.biz_name AS bizName, b.count AS count,
b.mom_ratio AS momRatio,
( SELECT q.manual_qoq FROM t_sr_manual_metric q WHERE q.status = 1 AND q.record_type = 'strategy_business_qoq' AND q.metric_code = 'manual_qoq' AND q.manual_qoq IS NOT NULL AND q.tab_type = #{tabType} AND q.strategy_class = '全部' #{strategyClass}
AND CONVERT(q.strategy_id USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(b.strategy_id USING utf8mb4) COLLATE utf8mb4_unicode_ci AND q.stat_month = STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d') AND CONVERT(q.biz_name USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(b.biz_name USING utf8mb4) COLLATE utf8mb4_unicode_ci AND (CONVERT(q.biz_code USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(COALESCE(b.biz_code, '') USING utf8mb4) COLLATE utf8mb4_unicode_ci OR q.biz_code = '') AND CONVERT(q.city_id USING utf8mb4) COLLATE utf8mb4_unicode_ci IN ('全部', CONVERT(COALESCE(NULLIF(b.city_id, ''), '全部') USING utf8mb4) COLLATE utf8mb4_unicode_ci) AND CONVERT(q.county_id USING utf8mb4) COLLATE utf8mb4_unicode_ci IN ('全部', CONVERT(COALESCE(NULLIF(b.county_id, ''), '全部') USING utf8mb4) COLLATE utf8mb4_unicode_ci) ORDER BY (CONVERT(q.biz_code USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(COALESCE(b.biz_code, '') USING utf8mb4) COLLATE utf8mb4_unicode_ci) DESC, (CONVERT(q.city_id USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(COALESCE(NULLIF(b.city_id, ''), '全部') USING utf8mb4) COLLATE utf8mb4_unicode_ci) DESC, (CONVERT(q.county_id USING utf8mb4) COLLATE utf8mb4_unicode_ci = CONVERT(COALESCE(NULLIF(b.county_id, ''), '全部') USING utf8mb4) COLLATE utf8mb4_unicode_ci) DESC, q.update_time DESC LIMIT 1 ) AS momRatio,
b.mom_ratio AS momRatio,
b.yoy_ratio AS yoyRatio FROM b WHERE
b.strategy_class = #{strategyClass}
b.tab_type = #{tabType} AND b.strategy_class = #{strategyClass}
AND b.strategy_id = #{strategyId} AND b. >= STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d') AND b. < DATE_ADD(STR_TO_DATE(CONCAT(#{statMonth}, '-01'), '%Y-%m-%d'), INTERVAL 1 MONTH) AND b.is_deleted = 0 and b.biz_name!='全部'
AND b.city_id = #{cityId} AND b.city_id = '999'
AND b.county_id = #{countyId}
